// Fungsi untuk mengambil data secara aman dari node search
const getOrganicData = (nodeName) => {
  try {
    const results = $(nodeName).all();
    // Mengambil array 'organic' dari hasil Serper API
    return results[0].json.organic || [];
  } catch (e) {
    return []; // Jika node gagal, berikan array kosong agar workflow tidak stop
  }
};

const nfaResults = getOrganicData('NFA');
const bisaResults = getOrganicData('BISA AI');
const vinixResults = getOrganicData('Vinix7');

// Gunakan DateTime.now() dari Luxon (bukan $now.format)
const currentTime = DateTime.now().toFormat('yyyy-MM-dd HH:mm');

// Gabungkan dan berikan label brand ke setiap berita
const finalData = [
  ...nfaResults.map(i => ({ json: { ...i, brand: 'NF Academy', processedAt: currentTime } })),
  ...bisaResults.map(i => ({ json: { ...i, brand: 'BISA AI', processedAt: currentTime } })),
  ...vinixResults.map(i => ({ json: { ...i, brand: 'Vinix 7', processedAt: currentTime } }))
];

return finalData;

// Mengambil seluruh item dari node sebelumnya
const allItems = $input.all();
const total = allItems.length;

// Menghitung mention per brand secara total
const counts = {
  nfa: allItems.filter(i => i.json.brand === "NF Academy").length,
  bisa: allItems.filter(i => i.json.brand === "BISA AI").length,
  vinix: allItems.filter(i => i.json.brand === "Vinix 7").length
};

// Menghitung Share of Voice (SOV)
const sov = {
  nfa: total > 0 ? ((counts.nfa / total) * 100).toFixed(1) : 0,
  bisa: total > 0 ? ((counts.bisa / total) * 100).toFixed(1) : 0,
  vinix: total > 0 ? ((counts.vinix / total) * 100).toFixed(1) : 0
};

// Menggabungkan seluruh teks berita menjadi satu blok teks untuk AI
let combinedText = "";
allItems.forEach(item => {
  combinedText += `[${item.json.brand}] ${item.json.title}: ${item.json.snippet}\n\n`;
});

// PENTING: Mengembalikan HANYA SATU objek (bukan array)
return {
  metrics: {
    processedAt: DateTime.now().toFormat('yyyy-MM-dd HH:mm'),
    total_mentions: total,
    breakdown: counts,
    share_of_voice: sov,
    dashboard_url: "https://docs.google.com/spreadsheets/d/1M8SHSn10yYdmJu1gW-HjmwEJT5d_Masj7wZZPgZK2oU/edit"
  },
  text_for_ai: combinedText
};

// Ambil AI analysis dari node chain (output: $json.text)
const aiAnalysis = $('Prompt untuk perbandingan').first().json.text || 'Analisis tidak tersedia';

// Ambil metrics dari node Menyiapkan Teks AI
const metrics = $('Menyiapkan Teks AI').first().json.metrics || {};
const sov = metrics.share_of_voice || {};
const counts = metrics.breakdown || {};
const processedAt = metrics.processedAt || '-';
const total = metrics.total_mentions || 0;

const nfaSov = parseFloat(sov.nfa) || 0;
const bisaSov = parseFloat(sov.bisa) || 0;
const vinixSov = parseFloat(sov.vinix) || 0;

// Format AI analysis untuk HTML
const aiFormatted = aiAnalysis
  .replace(/\n/g, '<br>')
  .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');

// Dynamic ringkasan eksekutif
const bisaLeading = bisaSov >= nfaSov;
const ringkasan = bisaLeading
  ? `Dalam percakapan digital (<strong>${total} mention</strong>), <span class="highlight">BISA AI</span> unggul tipis dengan <strong>${bisaSov}% Share of Voice</strong>, sementara <strong>NF Academy</strong> berada di <strong>${nfaSov}%</strong>.`
  : `Dalam percakapan digital (<strong>${total} mention</strong>), <span class="highlight">NF Academy</span> unggul dengan <strong>${nfaSov}% Share of Voice</strong>, sementara <strong>BISA AI</strong> berada di <strong>${bisaSov}%</strong>.`;

